inline void CSpriteFrame::Clip(int& sx, int& sy, int& sw, int& sh,
                               int& dx, int& dy, int dw, int dh,
                               unsigned char hflip,
                               unsigned char vflip) const
{
    if (hflip)
        sx = Width - (sw + sx);
    if (vflip)
        sy = Height - (sh + sy);

    if (dx < 0) {
        if (!hflip)
            sx -= dx;
        sw += dx;
        dx = 0;
    }
    if (dy < 0) {
        if (!vflip)
            sy -= dy;
        sh += dy;
        dy = 0;
    }
    if (sw + dx > dw) {
        if (hflip)
            sx += sw + dx - dw;
        sw = dw - dx;
    }
    if (sh + dy > dh) {
        if (vflip)
            sy += sh + dy - dh;
        sh = dh - dy;
    }

    int clipped;
    if (sx < CroppedX) {
        clipped = CroppedX - sx;
        if (!hflip)
            dx += clipped;
        sw -= clipped;
        sx = CroppedX;
    }
    if (sy < CroppedY) {
        clipped = CroppedY - sy;
        if (!vflip)
            dy += clipped;
        sh -= clipped;
        sy = CroppedY;
    }
    clipped = CroppedWidth + CroppedX;
    if (sw + sx > clipped) {
        if (hflip)
            dx += sw + sx - clipped;
        sw = clipped - sx;
    }
    clipped = CroppedHeight + CroppedY;
    if (sh + sy > clipped) {
        if (vflip)
            dy += sh + sy - clipped;
        sh = clipped - sy;
    }

    sx -= CroppedX;
    sy -= CroppedY;
}

